//! German nouns (always capitalized), and nouns that decline like adjectives (`angestellte`): 227 declensions learned from 143,824 dictionary words, the rules on a
//! word's ending that choose one, and the forms no declension gives.
//!
//! Generated by flexion-train from Wiktionary; don't edit by hand.

mod compounds;
mod gender;
mod irregular;
mod paradigms;
mod rules;
mod spellings;

pub use paradigms::Declension;

use crate::*;
use flexion::{Candidate, Grammar, Known, Reading};
use std::borrow::Cow;

/// Each cell's place in a paradigm.
#[allow(dead_code)]
pub mod cell {
    pub const NOM_SG: u16 = 0;
    pub const NOM_PL: u16 = 1;
    pub const GEN_SG: u16 = 2;
    pub const GEN_PL: u16 = 3;
    pub const DAT_SG: u16 = 4;
    pub const DAT_PL: u16 = 5;
    pub const ACC_SG: u16 = 6;
    pub const ACC_PL: u16 = 7;
}

/// The grammar: paradigms, the rules choosing one, irregular forms.
pub static GRAMMAR: Grammar<'static, Declension, u8, crate::Gender> = Grammar {
    orthography: crate::orthography::ORTHOGRAPHY,
    cells: 8,
    lemma_cell: Some(0),
    capitalized: true,
    paradigms: Cow::Borrowed(&paradigms::DECLENSIONS),
    paradigm: rules::DECLENSION,
    referrals: Cow::Borrowed(&gender::REFERRALS),
    feature: Some(gender::GENDER),
    compound: Some(compounds::COMPOUND),
    accent: None,
    laws: None,
    spellings: Cow::Borrowed(spellings::SPELLINGS),
    hidden: 0.0,
    irregular: Cow::Borrowed(irregular::IRREGULAR),
    smoothing: 2.0,
    sharpness: 1.0,
};

/// A noun form: which cell of its declension.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Cell {
    /// A noun in a case and number.
    Form(Case, Number),
}

impl Cell {
    /// Its place in a paradigm.
    pub const fn index(self) -> usize {
        let cell = match self {
            Cell::Form(Case::Nominative, Number::Singular) => cell::NOM_SG,
            Cell::Form(Case::Nominative, Number::Plural) => cell::NOM_PL,
            Cell::Form(Case::Genitive, Number::Singular) => cell::GEN_SG,
            Cell::Form(Case::Genitive, Number::Plural) => cell::GEN_PL,
            Cell::Form(Case::Dative, Number::Singular) => cell::DAT_SG,
            Cell::Form(Case::Dative, Number::Plural) => cell::DAT_PL,
            Cell::Form(Case::Accusative, Number::Singular) => cell::ACC_SG,
            Cell::Form(Case::Accusative, Number::Plural) => cell::ACC_PL,
        };
        cell as usize
    }
}

impl From<(Case, Number)> for Cell {
    fn from((case, number): (Case, Number)) -> Self {
        Cell::Form(case, number)
    }
}

/// A noun to inflect: its lemma, and what you know of it. The more you
/// tell, the surer its forms.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Noun<'w> {
    lemma: &'w str,
    given: Vec<(usize, &'w str)>,
    gender: Option<crate::Gender>,
}

impl<'w> Noun<'w> {
    /// The noun `lemma`, as the dictionary writes it.
    #[must_use]
    pub fn new(lemma: &'w str) -> Self {
        Noun {
            lemma,
            given: Vec::new(),
            gender: None,
        }
    }

    /// One of its forms you know (a principal part): readings that disagree
    /// with it are dropped.
    #[must_use]
    pub fn given(mut self, cell: impl Into<Cell>, form: &'w str) -> Self {
        self.given.push((cell.into().index(), form));
        self
    }

    /// Its gender, which says which cell its `referred` forms (see its
    /// declension) are taken from.
    #[must_use]
    pub fn gender(mut self, gender: Gender) -> Self {
        self.gender = Some(gender);
        self
    }

    fn known(&self) -> Known<'_, crate::Gender> {
        Known {
            forms: &self.given,
            feature: self.gender,
            full: false,
        }
    }

    /// Its likeliest form in `cell`.
    #[must_use]
    pub fn form(&self, cell: impl Into<Cell>) -> String {
        GRAMMAR.best(self.lemma, cell.into().index(), &self.known())
    }

    /// Every form it may have in `cell`, likeliest first, each with its
    /// probability and why.
    #[must_use]
    pub fn candidates(&self, cell: impl Into<Cell>) -> Vec<Candidate<'static>> {
        GRAMMAR.candidates(self.lemma, cell.into().index(), &self.known())
    }

    /// The declensions it may follow, likeliest first, each with its probability
    /// and why.
    #[must_use]
    pub fn declension(&self) -> Vec<Reading<'static, 'static, Declension>> {
        GRAMMAR.readings(self.lemma, &self.known())
    }
}
